      SUBROUTINE OCTGETCC     GET VALUES OF PARAMETERS DESCRIBING OCTUPOLECC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4C.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM6.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM26B.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'XRAN.CIN'CC     LOCAL VARIABLESC      INTEGER         IADR, IAP, IB, IDATA, IK3, IT      REAL            DATAR      EXTERNAL        DATAR, IDATAC------------------------------------------------------------------CC     MAGNET LENGTHC      IADR = I + 1      L = DATAR(IADR)      IF (PRAN25(1) .NE. 0.0) L = L + PRAN25(1)*XRAN(1)      L = L*UNITI(8)      LMAG = LCC     INDICES OF OTHER PARAMETERSC      IB = IPTOJ(2)      IAP = IPTOJ(3)      IK3 = IPTOJ(4)CC     MAGNETIC FIELD AND APERTUREC      IF (IK3 .GT. 0) GO TO 5      IADR = I + IB      B = DATAR(IADR)      IF (PRAN25(2) .NE. 0.0) B = B + PRAN25(2)*XRAN(2)      B = B*UNITI(9)*RI/PREFC      IF (IAP .NE. 0) THEN        IADR = I + IAP        AP = DATAR(IADR)      ELSE        WRITE (NOUT,9010) 9010   FORMAT (' *** ERROR *** OCTUPOLE APERTURE NOT GIVEN')        FLUSHL = .TRUE.        K3 = 0.0        AP = 0.0        GO TO 10      ENDIF      IF (AP .NE. 0.0) THEN        IF (PRAN25(3) .NE. 0.0) AP = AP + PRAN25(3)*XRAN(3)        AP = AP*UNITI(1)        K3 = B/(RI*AP**3)      ELSE        WRITE (NOUT,9009) 9009   FORMAT (' *** ERROR *** OCTUPOLE APERTURE SET TO ZERO')        FLUSHL = .TRUE.        K3 = 0.0      ENDIF      GO TO 10CC     NORMALIZED FIELD DERIVATIVE (MAD NOTATION)C    5 IADR = I + IK3      K3 = DATAR(IADR)      IF (PRAN25(4) .NE. 0.0)     1    K3 = K3 + PRAN25(4)*XRAN(4)      IF (MPMAD) K3 = K3/6.0      K3 = K3/UNITI(8)**3C   10 IT = IPTOJ(6)      IF (IT .EQ. 0) THEN        NUMTYP = IT      ELSE        NUMTYP = IDATA(I + IT)      ENDIF      RETURN      END